-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.storage_health()
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select pg_catalog.pg_database_size(pg_catalog.current_database()) < 300000000
$function$;

grant execute on function public.storage_health() to anon;
grant execute on function public.storage_health() to authenticated;
grant execute on function public.storage_health() to service_role;
